pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0) && caller != address(c.owner()));
        uint256 initialOwnerBalance = c.owner().balance;
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        assertTrue(success && c.owner().balance == initialOwnerBalance + address(c).balance);
    }
}

