// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        address originalOwner = c.owner();
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("go()"));
        // In the reference version, the call may revert if the external call fails, but here we just check the invariant
        if (success) {
            assertTrue(c.owner() == originalOwner);
        } else {
            assertTrue(true); // if it reverts, the state doesn't change
        }
    }
}

